 static Config config=new Config();static Map<String,Entry> ledger=new LinkedHashMap<>();
 static void save(){try{BossLedger.atomic(DIR.resolve("infinity-state.json"),JSON.toJson(ledger));}catch(Exception e){throw new IllegalStateException("Cannot save Infinity cooldown ledger",e);}}
 static void load(){try{Files.createDirectories(DIR);var p=DIR.resolve("infinity.json");if(!Files.exists(p))BossLedger.atomic(p,JSON.toJson(config));config=JSON.fromJson(Files.readString(p),Config.class);InfinityRules.select(config.snapWeights,0);if(config.snapCooldownSeconds<1800||config.snapCooldownSeconds>31536000||!Double.isFinite(config.rareSpawnMultiplier)||!Double.isFinite(config.typeSpawnMultiplier)||config.moneyReward<0||config.rareSpawnMultiplier<1||config.rareSpawnMultiplier>100||config.typeSpawnMultiplier<1||config.typeSpawnMultiplier>100||config.legendarySpecies==null||config.legendarySpecies.length==0)throw new IllegalArgumentException("Invalid infinity.json");pokemon("configure",new Class[]{double.class},config.rareSpawnMultiplier);p=DIR.resolve("infinity-state.json");if(Files.exists(p)){var type=new com.google.gson.reflect.TypeToken<LinkedHashMap<String,Entry>>(){}.getType();ledger=JSON.fromJson(Files.readString(p),type);if(ledger==null)throw new IllegalStateException("Empty Infinity state");}}catch(Exception e){throw new IllegalStateException("Cannot load Infinity configuration",e);}}
 public static boolean peace(Entity e){return e!=null&&(e.getCommandTags().contains("svframe_cosmic_peace")||e instanceof ServerPlayerEntity p&&has(p,"soul",false));}
